package org.rhythmlab.assist;
import android.app.Activity;import android.content.SharedPreferences;import android.graphics.*;import android.os.Handler;import android.view.*;import java.util.Locale;
/** Activity-owned, non-touchable HUD. Never covers input with a touch target. */
public final class LiveHud extends View {
 private final Activity activity;private final SharedPreferences prefs;private final Handler handler=new Handler();private final Paint paint=new Paint(3);private HudSample sample=HudSample.parse(null);private boolean attached;
 private final Runnable poll=new Runnable(){public void run(){if(!attached)return;sample=ReadOnlySource.sample();invalidate();handler.postDelayed(this,100);}};
 public LiveHud(Activity a,SharedPreferences p){super(a);activity=a;prefs=p;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}
 public void refresh(){hide();if(!Notice.accepted()||!prefs.getBoolean("live_hud",false)||activity.isFinishing())return;float density=getResources().getDisplayMetrics().density,scale=Math.max(.7f,Math.min(1.3f,prefs.getInt("hud_scale",100)/100f));int corner=prefs.getInt("hud_corner",1);WindowManager.LayoutParams w=new WindowManager.LayoutParams((int)(300*density*scale),(int)(184*density*scale),WindowManager.LayoutParams.TYPE_APPLICATION_PANEL,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,PixelFormat.TRANSLUCENT);w.token=activity.getWindow().getDecorView().getWindowToken();if(w.token==null)return;w.gravity=(corner>=2?Gravity.BOTTOM:Gravity.TOP)|((corner&1)==1?Gravity.RIGHT:Gravity.LEFT);w.x=(int)(12*density);w.y=(int)(12*density);try{activity.getWindowManager().addView(this,w);attached=true;handler.post(poll);}catch(RuntimeException e){attached=false;}}
 public void hide(){handler.removeCallbacks(poll);if(attached){attached=false;try{activity.getWindowManager().removeViewImmediate(this);}catch(RuntimeException ignored){}}}
 private void label(Canvas c,String text,float x,float y,float size,int color){paint.setColor(color);paint.setTextSize(size);paint.setStyle(Paint.Style.FILL);c.drawText(text,x,y,paint);}
 @Override protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/300f,getHeight()/184f);int alpha=Math.max(40,Math.min(100,prefs.getInt("hud_opacity",85)))*255/100;paint.setColor((alpha<<24)|0x101c2c);c.drawRoundRect(0,0,300,184,12,12,paint);label(c,"LIVE  ·  已判定音符 ACC",12,20,11,0xffaeefff);boolean ok=sample.available;label(c,"漏击 Miss",12,41,10,0xffc5d4e7);label(c,"击中 P+G",107,41,10,0xffc5d4e7);label(c,"当前 ACC",207,41,10,0xffc5d4e7);label(c,ok?""+sample.miss:"—",12,67,24,0xffffadab);label(c,ok?""+sample.hit():"—",107,67,24,0xfff5fbff);double acc=sample.accuracy();label(c,Double.isNaN(acc)?"—":String.format(Locale.ROOT,"%.2f%%",acc),207,67,19,0xff83eece);label(c,ok?"P "+sample.perfect+"   G "+sample.good+"   Bad "+sample.bad+"     已判 "+sample.judged()+(sample.total>=0?" / "+sample.total:""):"等待实际判定数据",12,86,10,0xffd1deee);
  float left=43,right=286,top=105,bottom=145;double low=100;for(int i=0;i<sample.points;i++)low=Math.min(low,sample.y(i));low=Math.max(0,Math.floor((low-2)/5)*5);if(low>95)low=95;paint.setColor(0xff51637b);paint.setStrokeWidth(.6f);c.drawLine(left,top,right,top,paint);c.drawLine(left,bottom,right,bottom,paint);label(c,"100%",8,top+3,9,0xffa7b9d1);label(c,String.format(Locale.ROOT,"%.0f%%",low),8,bottom+3,9,0xffa7b9d1);if(sample.points>0){int max=sample.x(sample.points-1),min=sample.x(0);Path path=new Path();paint.setColor(0xff86e8ff);paint.setStrokeWidth(1.8f);paint.setStyle(Paint.Style.STROKE);for(int i=0;i<sample.points;i++){float x=left+(right-left)*(sample.x(i)-min)/(float)Math.max(1,max-min),y=bottom-(float)((sample.y(i)-low)/(100-low))*(bottom-top);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}c.drawPath(path,paint);paint.setStyle(Paint.Style.FILL);if(sample.points==1)c.drawCircle(left,bottom-(float)((sample.y(0)-low)/(100-low))*(bottom-top),2,paint);label(c,min+" → "+max+" 个已判定音符",left,158,9,0xffa7b9d1);}else label(c,"开始判定后绘制真实曲线",left,129,10,0xffa7b9d1);String status=ReadOnlySource.status(sample);paint.setTextSize(10);while(paint.measureText(status)>276&&status.length()>1)status=status.substring(0,status.length()-1);label(c,status,12,175,10,0xffc4d7ed);c.restore();
 }
}
